SELECT branch, it_amount, essay_amount
FROM (
  SELECT branch, category, amount FROM sales_report
)
PIVOT (
  SUM(amount) FOR category
  IN ('IT' AS it_amount, '에세이' AS essay_amount)
)
ORDER BY branch;

SELECT branch, month_name, amount
FROM monthly_wide
UNPIVOT (
  amount FOR month_name IN (jan AS '01', feb AS '02')
)
ORDER BY branch, month_name;

