CREATE TABLE coupon (
  coupon_id VARCHAR2(5) PRIMARY KEY,
  code VARCHAR2(20) UNIQUE,
  discount NUMBER(6) NOT NULL,
  CONSTRAINT ck_coupon_discount CHECK (discount >= 0)
);

CREATE TABLE order_line (
  order_id VARCHAR2(3),
  line_no NUMBER(3),
  book_id VARCHAR2(3),
  CONSTRAINT pk_order_line PRIMARY KEY (order_id, line_no)
);

CREATE TABLE customers (
  customer_id VARCHAR2(3) PRIMARY KEY,
  name VARCHAR2(30 CHAR) NOT NULL
);
CREATE TABLE orders (
  order_id VARCHAR2(3) PRIMARY KEY,
  customer_id VARCHAR2(3),
  CONSTRAINT fk_orders_customer
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

