-- Oracle 세션 A · B01의 확정 qty는 10
UPDATE stock SET qty=8 WHERE book_id='B01';
SELECT qty FROM stock WHERE book_id='B01'; -- A는 8
-- 이 시점에 세션 B가 일반 SELECT를 새로 시작하면 10
COMMIT;
-- COMMIT 후 B가 일반 SELECT를 새로 시작하면 8

-- Oracle · 처음 qty=10이 확정된 상태
UPDATE stock SET qty=8 WHERE book_id='B01';
COMMIT;
UPDATE stock SET qty=6 WHERE book_id='B01';
ROLLBACK;
SELECT qty FROM stock WHERE book_id='B01';

-- Oracle · 처음 qty=10
UPDATE stock SET qty=8 WHERE book_id='B01';
SAVEPOINT s1;
UPDATE stock SET qty=5 WHERE book_id='B01';
SAVEPOINT s2;
UPDATE stock SET qty=1 WHERE book_id='B01';
ROLLBACK TO s1;
SELECT qty FROM stock WHERE book_id='B01'; -- 8

BEGIN TRANSACTION;
UPDATE dbo.stock SET qty=8 WHERE book_id='B01';
SAVE TRANSACTION s1;
UPDATE dbo.stock SET qty=5 WHERE book_id='B01';
ROLLBACK TRANSACTION s1;
COMMIT TRANSACTION;

-- Oracle · 처음 qty=10
