ROLLBACK;
SELECT qty FROM stock WHERE book_id='B01'; -- 8

-- Oracle · t는 PK(id), 값은 (1,100)만 있고 확정됨
UPDATE t SET amount=120 WHERE id=1;
INSERT INTO t (id,amount) VALUES (1,999); -- PK 중복 오류
