-- 소유자 bookstore가 기존 사용자 analyst에게 부여
GRANT SELECT ON bookstore.stock TO analyst;
GRANT UPDATE (qty) ON bookstore.stock TO analyst;

-- 부여한 SELECT 권한을 회수
REVOKE SELECT ON bookstore.stock FROM analyst;

-- 필요한 권한을 가진 계정이 각각 실행한다는 가정
CREATE ROLE stock_reader;
GRANT SELECT ON bookstore.stock TO stock_reader;
GRANT stock_reader TO analyst;

-- Oracle · 객체 권한을 다른 사용자에게 재부여하도록 허용
GRANT SELECT ON bookstore.stock TO user_a WITH GRANT OPTION;
-- user_a는 user_b에게 SELECT를 부여할 수 있음

-- Oracle · 시스템 권한의 재부여 허용
GRANT CREATE TABLE TO user_a WITH ADMIN OPTION;

-- Oracle · B01 qty=10 확정, 자동 COMMIT OFF
UPDATE stock SET qty=8 WHERE book_id='B01';
GRANT SELECT ON stock TO analyst; -- 소유자가 성공적으로 실행
ROLLBACK;
-- qty는 8, 권한 부여도 ROLLBACK으로 취소되지 않음

-- Oracle · stock의 소유자, 필요한 권한 충족
-- 시작: B01 qty=10 확정 / analyst는 stock 권한 없음
UPDATE stock SET qty=8 WHERE book_id='B01';
SAVEPOINT after_sale;
UPDATE stock SET qty=7 WHERE book_id='B01';
ROLLBACK TO after_sale;
COMMIT;
GRANT SELECT ON stock TO analyst;
REVOKE SELECT ON stock FROM analyst;
ROLLBACK;

